import App, { props, sequences, state } from 'cerebral'
import { Container, connect } from '.'

import React from 'react'
import { render, screen, act } from '@testing-library/react'
import { fireEvent } from '@testing-library/dom'
import assert from 'assert'

// Helper function to get rendered component instance via ref
function getComponentRef(Component) {
  let componentRef = null
  const WrappedWithRef = (props) => {
    return (
      <Component
        ref={(ref) => {
          componentRef = ref
        }}
        {...props}
      />
    )
  }
  return { WrappedWithRef, getRef: () => componentRef }
}

describe('React', () => {
  describe('container', () => {
    it('should expose app components', () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })
      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        (props) => {
          return <div data-testid="test-div">{props.foo}</div>
        }
      )

      render(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      assert.strictEqual(screen.getByTestId('test-div').innerHTML, 'bar')
    })

    it('should throw when no app provided', () => {
      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        (props) => {
          return <div>{props.foo}</div>
        }
      )
      const originError = console.error
      console.error = () => {}
      assert.throws(
        () => {
          render(
            <Container>
              <TestComponent />
            </Container>
          )
        },
        (err) => {
          console.error = originError
          if (err instanceof Error) {
            return (
              err.message ===
              'Cerebral - You are not passing a Cerebral app to Container'
            )
          }
        }
      )
    })

    it('should throw when container component is not provided', () => {
      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        (props) => {
          return <div>{props.foo}</div>
        }
      )
      const originError = console.error
      console.error = () => {}
      assert.throws(
        () => {
          render(<TestComponent />)
        },
        (err) => {
          console.error = originError
          if (err instanceof Error) {
            return (
              err.message ===
              'Cerebral - Can not find controller, did you remember to use the Container component? Read more at: http://cerebraljs.com/docs/api/components.html#react'
            )
          }
        }
      )
    })

    it('should be able to unregister component from container after unmounting component', () => {
      const app = App(
        {
          state: {
            foo: 'bar',
          },
        },
        {
          devtools: {
            init() {},
            send() {},
            updateWatchMap() {},
            updateComputedMap() {},
            sendWatchMap() {},
          },
        }
      )

      const { WrappedWithRef, getRef } = getComponentRef(
        connect(
          {
            foo: state`foo`,
          },
          (props) => {
            return <div data-testid="test-div">{props.foo}</div>
          }
        )
      )

      const { unmount } = render(
        <Container app={app}>
          <WrappedWithRef />
        </Container>
      )

      const TestComponentRef = getRef()

      assert.strictEqual(TestComponentRef._isUnmounting, undefined)
      assert.strictEqual(screen.getByTestId('test-div').innerHTML, 'bar')

      unmount()

      assert.strictEqual(TestComponentRef.view.isUnmounted, true)
      assert.deepStrictEqual(app.dependencyStore.getAllUniqueEntities(), [])
    })
  })

  describe('connect', () => {
    it('should convert component to json', () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })
      const MyComponent = (props) => {
        return <div>{props.foo}</div>
      }
      MyComponent.displayName = 'Test'

      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        MyComponent
      )

      const { WrappedWithRef, getRef } = getComponentRef(TestComponent)

      render(
        <Container app={app}>
          <WrappedWithRef />
        </Container>
      )

      assert.strictEqual(getRef().toJSON(), 'Test')
    })

    it('should render only ones where multiple state matches', () => {
      const app = App({
        state: {
          foo: 'bar',
          bar: 'foo',
        },
        sequences: {
          test: [
            ({ store }) => {
              store.set(state`foo`, 'bar2')
              store.set(state`bar`, 'foo2')
            },
          ],
        },
      })
      let renderCount = 0
      const TestComponent = connect(
        {
          foo: state`foo`,
          bar: state`bar`,
        },
        (props) => {
          renderCount++
          return <div data-testid="test-div">{props.foo}</div>
        }
      )

      render(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      assert.strictEqual(screen.getByTestId('test-div').innerHTML, 'bar')
      assert.strictEqual(renderCount, 1)

      act(() => {
        app.getSequence('test')()
      })

      assert.strictEqual(renderCount, 2)
    })

    it('should only rerender affected components', () => {
      let renderCount = 0
      const app = App({
        state: {
          foo: 'bar',
        },
        sequences: {
          methodCalled: [({ store }) => store.set(state`foo`, 'bar2')],
        },
      })

      class TestComponentClass2 extends React.Component {
        render() {
          renderCount++
          return <div />
        }
      }
      const TestComponent2 = connect(TestComponentClass2)

      class TestComponentClass extends React.Component {
        callSignal() {
          this.props.methodCalled()
        }

        render() {
          renderCount++
          return (
            <div>
              <button
                data-testid="action-button"
                onClick={() => this.callSignal()}
              >
                Action
              </button>
              <TestComponent2 />
            </div>
          )
        }
      }

      const TestComponent = connect(
        {
          foo: state`foo`,
          methodCalled: sequences`methodCalled`,
        },
        TestComponentClass
      )

      render(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      act(() => {
        fireEvent.click(screen.getByTestId('action-button'))
      })

      assert.strictEqual(renderCount, 3)
    })

    it('should allow props tag and computed', () => {
      const app = App({
        state: {
          foo: {
            baz: 'mip',
          },
          aComputed: (get) => get(props`foo`),
        },
      })
      const TestComponent = connect(
        {
          a: state`aComputed`,
          b: props`bar.id`,
          c: state`foo.${props`propKey`}`,
        },
        ({ a, b, c }) => {
          return <div data-testid="test-div">{a + b + c}</div>
        }
      )

      render(
        <Container app={app}>
          <TestComponent foo="bar" bar={{ id: '1' }} propKey="baz" />
        </Container>
      )

      assert.strictEqual(screen.getByTestId('test-div').innerHTML, 'bar1mip')
    })

    it('should update on props change', () => {
      const app = App({})

      class TestComponentClass2 extends React.Component {
        render() {
          return <div data-testid="test-div">{this.props.foo}</div>
        }
      }
      const TestComponent2 = connect(TestComponentClass2)

      class TestComponentClass extends React.Component {
        constructor(props) {
          super(props)
          this.state = { foo: 'bar' }
          this.handlePathChange = this.handlePathChange.bind(this)
        }

        handlePathChange() {
          this.setState({
            foo: 'bar2',
          })
        }

        render() {
          return (
            <span>
              <TestComponent2 foo={this.state.foo} />
              <button
                data-testid="change-button"
                onClick={this.handlePathChange}
              >
                Change
              </button>
            </span>
          )
        }
      }

      const TestComponent = connect(TestComponentClass)

      render(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      assert.strictEqual(screen.getByTestId('test-div').innerHTML, 'bar')

      act(() => {
        fireEvent.click(screen.getByTestId('change-button'))
      })

      assert.strictEqual(screen.getByTestId('test-div').innerHTML, 'bar2')
    })

    it('should expose a merge signature', () => {
      const app = App({
        state: {
          foo: 'bar',
          bar: 'baz',
        },
      })
      const TestComponent = connect(
        {
          a: props`foo`,
          b: state`foo`,
        },
        (deps, props, get) => {
          return {
            a: deps.a,
            b: deps.b,
            c: props.foo + '!!!',
            d: get(state`bar`),
          }
        },
        ({ a, b, c, d }) => {
          return <div data-testid="test-div">{a + b + c + d}</div>
        }
      )

      render(
        <Container app={app}>
          <TestComponent foo="bar" />
        </Container>
      )

      assert.strictEqual(
        screen.getByTestId('test-div').innerHTML,
        'barbarbar!!!baz'
      )
    })
  })
})
